target.css:
:root {
  --brand-dark: #0f1c2e;
  --brand-accent: #2563eb;
  --brand-accent-light: #dbeafe;
  --brand-green: #16a34a;
  --brand-green-light: #dcfce7;
  --text-primary: #0f1c2e;
  --text-secondary: #64748b;
  --text-muted: #94a3b8;
  --surface: #ffffff;
  --surface-alt: #f8fafc;
  --border: #e2e8f0;
  --highlight-bg: #eff6ff;
  --highlight-text: #1d4ed8;
  --badge-bg: #fef9c3;
  --badge-text: #854d0e;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  margin: 0;
  padding: 20px;
  box-sizing: border-box;
}

.pitch-card {
  background: var(--surface);
  border: 1.5px solid var(--border);
  border-radius: 16px;
  padding: 20px;
  width: 500px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.pitch-header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.logo-mark {
  width: 42px;
  height: 42px;
  background: var(--brand-accent);
  color: var(--surface);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  font-weight: 800;
  flex-shrink: 0;
}

.header-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}

.company-name {
  font-size: 18px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.2;
}

.tagline {
  font-size: 12px;
  color: var(--text-secondary);
  line-height: 1.4;
}

.stage-badge {
  background: var(--badge-bg);
  color: var(--badge-text);
  font-size: 11px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 20px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.metrics-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}

.metric {
  background: var(--surface-alt);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 10px 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.metric.highlight {
  background: var(--highlight-bg);
  border-color: var(--brand-accent);
}

.metric-value {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.2;
}

.metric.highlight .metric-value {
  color: var(--highlight-text);
}

.metric-label {
  font-size: 11px;
  color: var(--text-muted);
  font-weight: 500;
  line-height: 1.3;
}

.pitch-body {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.problem-block,
.solution-block {
  border-radius: 10px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.problem-block {
  background: #fff7ed;
  border: 1px solid #fed7aa;
}

.solution-block {
  background: var(--brand-green-light);
  border: 1px solid #86efac;
}

.block-title {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin: 0;
  color: var(--text-secondary);
}

.block-text {
  font-size: 13px;
  color: var(--text-primary);
  line-height: 1.5;
  margin: 0;
}

.pitch-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid var(--border);
  padding-top: 14px;
}

.founder-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.founder-avatar {
  width: 36px;
  height: 36px;
  background: var(--brand-dark);
  color: var(--surface);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
  flex-shrink: 0;
}

.founder-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.founder-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  line-height: 1.3;
}

.founder-role {
  font-size: 11px;
  color: var(--text-muted);
  line-height: 1.3;
}

.cta-btn {
  background: var(--brand-accent);
  color: var(--surface);
  border: none;
  border-radius: 8px;
  padding: 9px 18px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  line-height: 1;
}

